# Let me double-check by mapping columns to values
# Test input row 6: [1, 2, 1, 8, 1, 1, 1, 8, 1, 2, 1]

test_input_row = [1, 2, 1, 8, 1, 1, 1, 8, 1, 2, 1]
col_to_val = {}
for col, val in enumerate(test_input_row):
    if val != 1:
        col_to_val[col] = val
        print(f"Col {col} has value {val}")

# According to value-based height rule:
# value 2 -> height 4
# value 8 -> height 3

# Generate output
output = [[0]*11 for _ in range(9)]
source_row = 6

# Columns with value 2: cols 1 and 9
# Columns with value 8: cols 3 and 7
for col, val in col_to_val.items():
    if val == 2:
        height = 4
    else:  # val == 8
        height = 3

    start_row = source_row - height + 1
    for row in range(start_row, source_row + 1):
        if row == source_row:
            output[row][col] = val
        else:
            output[row][col] = 1

print("Output:")
for row in output:
    print(' '.join(str(c) for c in row))

# Final output - let me verify the row-by-row structure
output = [[0]*11 for _ in range(9)]
source_row = 6
lines = [(1, 2, 4), (3, 8, 3), (7, 8, 3), (9, 2, 4)]

for col, val, height in lines:
    start_row = source_row - height + 1
    for row in range(start_row, source_row + 1):
        if row == start_row or row == source_row:
            output[row][col] = val
        else:
            output[row][col] = 1

print("Final output to submit:")
for row in output:
    print(' '.join(str(c) for c in row))

